import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import type { DataQuality, Recit, Region } from "@/data/schemas";
import { isAllowedMediaUrl, parseWktPoint, slugify } from "../../scripts/lib/util";

// Generated by `npm run data:build` (also run by predev/prebuild and CI).
const read = <T>(name: string): T =>
  JSON.parse(readFileSync(join(process.cwd(), "src/data/generated", name), "utf8")) as T;

const recits = read<Recit[]>("recits.json");
const regions = read<Region[]>("regions.json");
const quality = read<DataQuality>("data-quality.json");
const regionsGeo = read<{ features: { properties: { id: string } }[] }>("regions.geojson");

const recit = (slug: string) => {
  const r = recits.find((x) => x.slug === slug);
  if (!r) throw new Error(`missing ${slug}`);
  return r;
};

describe("phase 2 acceptance", () => {
  it("Yennenga is told in Nakambé and is interactive", () => {
    const y = recit("yennenga-la-cavaliere");
    expect(y.regionIds).toEqual(["loc_nakambe"]);
    expect(y.estInteractif).toBe(true);
    expect(y.type).toBe("mythe_fondateur");
  });

  it("Sabou is told in Nando", () => {
    expect(recit("crocodiles-de-sabou").regionIds).toEqual(["loc_nando"]);
  });

  it("Bazoulé and Dafra get a region through the spatial join", () => {
    expect(recit("crocodiles-de-bazoule").regionIds).toHaveLength(1);
    expect(recit("silures-de-dafra").regionIds).toEqual(["loc_guiriko"]);
    const joined = quality.localitesSansParent.rattacheesParJointureSpatiale.map((x) => x.id);
    expect(joined).toEqual(expect.arrayContaining(["loc_bazoule", "loc_bobo_dioulasso_dafra"]));
  });

  it("regions.geojson has exactly 17 features, all matched to the ontology", () => {
    expect(regionsGeo.features).toHaveLength(17);
    const ids = new Set(regions.map((r) => r.id));
    for (const f of regionsGeo.features) expect(ids.has(f.properties.id)).toBe(true);
  });

  it("anchored stories take the site's WKT point", () => {
    expect(recit("crocodiles-de-sabou").lieu).toMatchObject({ source: "site", lon: -2.233, lat: 12.067 });
    expect(recit("yennenga-la-cavaliere").lieu?.source).toBe("localite");
  });

  it("Yennenga's choices point to existing scenes", () => {
    const scenes = recit("yennenga-la-cavaliere").versions.flatMap((v) => v.scenes);
    const orders = new Set(scenes.map((s) => s.ordre));
    const choices = scenes.flatMap((s) => s.choix);
    expect(choices).toHaveLength(2);
    for (const c of choices) expect(orders.has(c.cibleOrdre)).toBe(true);
    expect(choices.filter((c) => c.vraieFin)).toHaveLength(1);
  });

  it("missing mother-tongue recordings are flagged", () => {
    // Yennenga has a Mooré version, Sabou (also Mossi) has none.
    expect(recit("yennenga-la-cavaliere").langueAEnregistrer).not.toContain("langue_moore");
    expect(recit("crocodiles-de-sabou").langueAEnregistrer).toContain("langue_moore");
  });

  it("restricted and unconsented stories are not publishable", () => {
    expect(recit("silures-de-dafra").restreint).toBe(true);
    expect(recits.every((r) => !r.publiable)).toBe(true); // no consent recorded yet
  });

  it("aliases are merged and generic groups ignored", () => {
    expect(quality.aliases.merged).toBe(8);
    expect(quality.ethnies.generiquesIgnorees).toContain("ethnie_plusieurs_ethnies");
  });

  it("external media URLs never reach the app", () => {
    expect(quality.mediasExternesMasques).toBeGreaterThan(0);
    const urls = recits.flatMap((r) =>
      r.versions.flatMap((v) => [v.audio, v.vtt, ...v.scenes.flatMap((s) => [s.illustration, s.animation])]),
    );
    for (const url of urls.filter(Boolean)) expect(isAllowedMediaUrl(url!)).toBe(true);
  });
});

describe("pipeline helpers", () => {
  it("slugify", () => {
    expect(slugify("Djôrô")).toBe("djoro");
    expect(slugify("Nakambé")).toBe("nakambe");
    expect(slugify("Fada N’Gourma")).toBe("fada-n-gourma");
  });
  it("parseWktPoint", () => {
    expect(parseWktPoint("POINT (-2.233 12.067)")).toEqual([-2.233, 12.067]);
    expect(parseWktPoint("LINESTRING (0 0, 1 1)")).toBeUndefined();
  });
  it("isAllowedMediaUrl", () => {
    expect(isAllowedMediaUrl("media/audio/demo-bip.opus")).toBe(true);
    expect(isAllowedMediaUrl("https://abc.public.blob.vercel-storage.com/x.webp")).toBe(true);
    expect(isAllowedMediaUrl("https://th.bing.com/th/id/R.123")).toBe(false);
    expect(isAllowedMediaUrl("https://en.wikipedia.org/wiki/Ngoni")).toBe(false);
  });
});
